-- raiden_lift_fatality_test.lua
--
-- Drives Raiden's F,F,F + LK lift/lightning fatality (do_raiden_lift_fatal,
-- MKDEATH.ASM) during FINISH HIM and checks it plays its authored frames and
-- ends the round cleanly.
--
-- Layout (data/RAIDELEC.WAX, generated by tools/raiden_lift_wax_import.py):
-- Raiden walks a_death_zap1 (RN1DETHBLO1, then one row per WAX step), the bolt
-- a_death_bolt1 from the first step, and the victim is posed from Raiden's row
-- loop off rd_lift_vic_script.  The WAX detector below checks every frame from
-- the one the bolt appears on, against where the WAX timeline says it should
-- be: Raiden's body frame, the bolt frame, the victim's pose family, his anchor
-- offset from Raiden (sign-flipped with Raiden's facing) and his facing.
--
-- The original crash this rig was built for: the row walkers  They used to carry that count in
-- a2 across `calla prcslp`, but the scheduler only preserves a7-a12
-- (MPROC.ASM: "mmtm a1,a7,a8,a9,a10,a11,a12").  a2 therefore came back holding
-- another process's leftovers and the dsj ran an arbitrary number of times,
-- marching a9/a11 straight past their own terminators into raw ROM.  The
-- visible result is garbage frames and/or a hang, which is why the whole move
-- was compiled out behind raiden_lift_fatal_enable.
--
-- So the core detector is: every frame the fatality is live, Raiden's object
-- and the bolt object must be pointing at art that actually exists in the
-- Raiden art tables.  A SAG that matches no label in MKRD.TBL / RDSZAP.TBL /
-- MKBOLTS.TBL is the ROM-walk, caught the instant it is drawn.
--
-- Flow:
--   1. Direct-select P1 Raiden (ft_raiden=7) vs P2 Liu Kang (ft_kang=1), reach fight.
--      Liu Kang because RAIDELEC.WAX authors the victim on KANG5/6/10 art.
--   2. Force FINISH HIM: winner_status=3, f_death=0, victim wake=dizzy_dude.
--   3. Snap P1 inside the 0x52 range gate, then tap Forward,Forward,Forward+LK
--      until f_death==3 (init_death_blow's fatality # for this move).
--   4. Watch every frame until death_blow_complete clears f_death, running the
--      unknown-SAG / lockup / hang detectors the whole way.
--
-- Env knobs:
--   RDLF_LOG=path        log path
--   RDLF_OBSERVE=N       frames to keep watching after f_death clears (default 300 - the
--                        head only comes to rest ~220 frames after the fatality ends,
--                        so less than that cuts its bounces off and fails on the count)
--   RDLF_HANG=N          frames the fatality may stay live before it's a hang
--                        (default 900; the authored run is ~110 game ticks)

local ROOT = os.getenv("MK2_ROOT") or "C:/Users/you/Workplace/mk2-main"
ROOT = ROOT:gsub("\\", "/")

local function getenv_int(name, default)
    local raw = os.getenv(name)
    if not raw or raw == "" then return default end
    return tonumber(raw) or default
end

local LOG_PATH = os.getenv("RDLF_LOG") or (ROOT .. "/tools/raiden_lift_fatality_test.log")
local OBSERVE = getenv_int("RDLF_OBSERVE", 300)
local HANG_LIMIT = getenv_int("RDLF_HANG", 900)

local logfh = io.open(LOG_PATH, "w")
local frame = 0
-- RDLF_SND=1: tap the hardware sound latch and log every track code with the
-- frame it was sent on, relative to the fatality.  The latch carries the
-- RESOLVED DCS TRACK, not the code the source sends (tsound 0c7h is not 0c7h
-- on the wire), so this does not try to name codes - the PATTERN is the
-- evidence: the chime at the top, the victim's death voice as the bolt lands,
-- and one code repeating on the electrocution stretch's 20-tick beat.
-- Shape and the rolling-pair trap are sweep_addon_suddeath.lua's.
local SND_TAP = (os.getenv("RDLF_SND") or "0") ~= "0"
local SND_PORT, SND_LO, SND_HI = 0x01d01030, 0x01d00000, 0x01d01fff
local snd_pending, snd_log, snd_handle = nil, {}, nil
local raw_print = print
print = function(...)
    local parts = {}
    for i = 1, select("#", ...) do parts[#parts + 1] = tostring(select(i, ...)) end
    local line = table.concat(parts, "\t")
    raw_print(line)
    if logfh then logfh:write(line, "\n"); logfh:flush() end
end
local function log(fmt, ...)
    print("[rdlf] " .. (select("#", ...) > 0 and string.format(fmt, ...) or tostring(fmt)))
end
local function hx(v)
    if v == nil then return "na" end
    return string.format("0x%08x", v & 0xffffffff)
end
local function s16(v)
    v = v & 0xffff
    if v >= 0x8000 then return v - 0x10000 end
    return v
end

local symbols = {}
do
    local map_path = ROOT .. "/src/mk2.map"
    local fh = io.open(map_path, "r")
    if not fh then map_path = ROOT .. "/src/MK2.MAP"; fh = io.open(map_path, "r") end
    if fh then
        for line in fh:lines() do
            for addr, name in line:gmatch("(%x%x%x%x%x%x%x%x)%s+([%w_%.]+)") do
                symbols[name] = tonumber(addr, 16)
            end
        end
        fh:close()
        log("loaded symbols from %s", map_path)
    else
        log("WARN no linker map found")
    end
end
local function sym(name, fallback)
    local v = symbols[name]
    if v ~= nil then return v end
    log("WARN missing symbol %s", name)
    return fallback or 0
end

