local function r16(a) return space:read_u16(a) end
local function r32(a) return space:read_u32(a) end
local function w16(a, v) space:write_u16(a, v & 0xffff) end
local function w32(a, v) space:write_u32(a, v & 0xffffffff) end

--------------------------------------------------------------------------
-- SAG -> label maps, straight out of the source art tables.
--------------------------------------------------------------------------
-- Every label that names a SAG.  Two records can share pixels (TMFLIPPED1A and
-- TMFLIPS2A), and the first-wins maps then name the drawn piece after the
-- other one - so a pose check has to accept any of them.
local SAG_ALIASES = {}
local function load_sags(path, into, count_only_matching)
    local fh = io.open(path, "r")
    if not fh then log("WARN cannot open %s", path); return 0 end
    local n, current = 0, nil
    for line in fh:lines() do
        -- TBL art records use "LABEL:"; the handful of art records defined
        -- inline in .ASM use a bare label.  Accepting ANY bare label there
        -- drags in code labels (first_image, ...) and mislabels real frames,
        -- so bare labels are only taken when they name Raiden art.
        local label = line:match("^([%w_]+):")
            or line:match("^(RN[%w_]*)%s*$")
            or line:match("^(KLUDGE_[%w_]*)%s*$")
        if label then current = label end
        if current then
            local raw = line:match("%.long%s+0?x?([%x]+)[Hh]")
            if raw then
                -- Register the full value and the 24-bit form: object SAG words
                -- are read back masked in some paths and whole in others.
                local sag = tonumber(raw, 16)
                for _, k in ipairs({ sag, sag & 0x00ffffff }) do
                    SAG_ALIASES[k] = SAG_ALIASES[k] or {}
                    table.insert(SAG_ALIASES[k], current)
                end
                if into[sag] == nil then into[sag] = current end
                sag = sag & 0x00ffffff
                if into[sag] == nil then into[sag] = current end
                current = nil
                n = n + 1
            end
        end
    end
    fh:close()
    return n
end

-- Everything Raiden's own player object may legally point at.
local raiden_sags = {}
-- Everything the bolt overlay may legally point at.
local bolt_sags = {}
-- Every art label in the tree, for naming the victim's pose whoever he is.
local all_sags = {}

do
    -- Every table Raiden's own player object can legally draw from.  MKRD2.TBL
    -- holds the RN2DETHBLO* art this fatality uses for its intro, and the
    -- shared MKFATAL/MKFALL art shows up on the surrounding frames.
    local body_files = { "MKRD.TBL", "MKRD2.TBL", "MKRDWALK.TBL", "RDSZAP.TBL",
                         "RNHEADHO.TBL", "MKFATAL.TBL", "MKFALL.TBL",
                         "MKRD.ASM", "MKGUYS.ASM", "MKFALL.ASM" }
    local parts = {}
    for _, f in ipairs(body_files) do
        parts[#parts + 1] = string.format("%s=%d", f, load_sags(ROOT .. "/src/" .. f, raiden_sags))
    end
    -- KLUDGE_RN1DETHBOLT1A is defined inline in MKRD.ASM, not in a TBL.
    local nb = load_sags(ROOT .. "/src/MKBOLTS.TBL", bolt_sags)
    local nb2 = load_sags(ROOT .. "/src/MKRD.ASM", bolt_sags)
    log("body SAGs: %s | bolt SAGs: MKBOLTS.TBL=%d MKRD.ASM=%d",
        table.concat(parts, " "), nb, nb2)

    -- Whole-tree map so the victim's pose can be named no matter which
    -- character module it lives in (the *BACKBREAK / *DRAIN families are
    -- spread across every per-fighter TBL).
    local total = 0
    local lfs_ok, dirlist = pcall(function()
        local t, p = {}, io.popen('dir /b "' .. ROOT:gsub("/", "\\") .. '\\src\\*.TBL"')
        if p then for l in p:lines() do t[#t + 1] = l end p:close() end
        return t
    end)
    if lfs_ok and dirlist then
        for _, f in ipairs(dirlist) do
            total = total + load_sags(ROOT .. "/src/" .. f, all_sags)
        end
    end
    log("all-tree SAGs: %d records from %d TBLs", total, dirlist and #dirlist or 0)
end

-- Label for an object, or nil if its art is not in the expected family.
local function obj_label(obj, tbl)
    if obj == 0 then return nil, 0 end
    local cands = { r32(obj + O.osag) }
    local img = r32(obj + O.oimg)
    if img ~= 0 then cands[#cands + 1] = r32(img) end
    for _, raw in ipairs(cands) do
        local lab = tbl[raw] or tbl[raw & 0x00ffffff]
        if lab then return lab, raw end
    end
    return nil, cands[#cands]
end

local function walk(fn)
    for _, list in ipairs({ A.objlst, A.objlst2, A.objlst3 }) do
        if list ~= 0 then
            local obj, guard, seen = r32(list), 0, {}
            while obj ~= 0 and guard < 400 do
                if seen[obj] then return "cycle" end
                seen[obj] = true
                fn(obj)
                obj = r32(obj + O.next)
                guard = guard + 1
            end
        end
    end
    return nil
end

local function object_count()
    local n = 0
    local err = walk(function() n = n + 1 end)
    return n, err
end

local function count_procs()
    local p, n, guard, seen = r32(A.active), 0, 0, {}
    while p ~= 0 and guard < 400 do
        if seen[p] then return n, true end
        seen[p] = true
        n = n + 1
        p = r32(p + P.next)
        guard = guard + 1
    end
    return n, false
end

-- The bolt overlay is a multipart effect object carrying RN1DETHBOLT art.
-- Find it by matching its SAG against the bolt family.
local function find_bolt()
    local found, fsag = nil, 0
    walk(function(obj)
        if found then return end
        if obj == r32(A.p1_obj) or obj == r32(A.p2_obj) then return end
        local lab, sag = obj_label(obj, bolt_sags)
        if lab and lab:match("^K?L?U?D?G?E?_?RN1DETHBOLT") then found, fsag = lab, sag end
    end)
    return found, fsag
end

local function p1_action()
    local p = r32(A.p1_proc)
    if p == 0 then return 0xffff end
    return r16(p + P.action)
end

local function x_dist()
    local a, b = r32(A.p1_obj), r32(A.p2_obj)
    if a == 0 or b == 0 then return -1 end
    return math.abs(r16(a + O.oxpos) - r16(b + O.oxpos))
end

-- Is this object actually linked into a display list (i.e. will it be drawn)?
local function on_display(target)
    local hit = false
    walk(function(obj) if obj == target then hit = true end end)
    return hit
end

local function state_line(tag)
    local p1o, p2o = r32(A.p1_obj), r32(A.p2_obj)
    local blab = select(1, find_bolt())
    local rlab = select(1, obj_label(p1o, raiden_sags))
    local vlab, vsag = obj_label(p2o, all_sags)
    local p1x, p1y, p2x, p2y = 0, 0, 0, 0
    if p1o ~= 0 then p1x, p1y = s16(r16(p1o + O.oxpos)), s16(r16(p1o + O.oypos)) end
    if p2o ~= 0 then p2x, p2y = s16(r16(p2o + O.oxpos)), s16(r16(p2o + O.oypos)) end
    local nobj, oerr = object_count()
    local nproc, pcyc = count_procs()
    return string.format(
        "%s gs=%d ws=%d fdeath=%d cam=%d/%d/%d vy=%d noy=%d p1act=0x%04x p1hp=%d p2hp=%d p1=(%d,%d) p2=(%d,%d) body=%s bolt=%s vic=%s%s objs=%d%s procs=%d%s",
        tag, r16(A.gstate), r16(A.winner_status), s16(r16(A.f_death)),
        s16(r16(A.worldtly + 16)), s16(r16(A.ceiling_y)), s16(r16(A.climb_limit)),
        (function(v) if v >= 0x80000000 then v = v - 0x100000000 end return v end)(r32(A.scrolly)),
        r16(A.f_noscrolly), p1_action(),
        r16(A.p1_bar), r16(A.p2_bar), p1x, p1y, p2x, p2y,
        rlab or ("?" .. hx(select(2, obj_label(p1o, raiden_sags)))),
        blab or "-",
        vlab or ("?" .. hx(vsag)),
        (p2o ~= 0 and on_display(p2o)) and "" or "[OFFLIST]",
        nobj, oerr and ("!" .. oerr) or "", nproc, pcyc and "!cycle" or "")
end

local function main_screen()
    local ok, s = pcall(function() return manager.machine.screens[":screen"] end)
    if ok and s then return s end
    ok, s = pcall(function() return manager.machine.screens:at(1) end)
    return ok and s or nil
end

local function snap(label)
    local s = main_screen()
    local ok = false
    if s then ok = pcall(function() s:snapshot() end) end
    log("SNAP idx=%04d frame=%d label=%s ok=%s", snap_index, frame, label, tostring(ok))
    snap_index = snap_index + 1
end

local function finish(ok, reason)
    if finished then return end
    finished = true
    snap(ok and "final_ok" or ("final_" .. reason))
    if SND_TAP then
        local seen = {}
        for _, e in ipairs(snd_log) do
            local rel = fatal_frame > 0 and (e.f - fatal_frame) or -9999
            log("SND rel=%-4d track=%04x", rel, e.code)
            seen[e.code] = (seen[e.code] or 0) + 1
        end
        local parts = {}
        for c, n in pairs(seen) do parts[#parts + 1] = string.format("%04x x%d", c, n) end
        table.sort(parts)
        log("SND totals: %s", table.concat(parts, ", "))
    end
    log("body frames seen: %s", table.concat(body_seq, ","))
    log("bolt frames seen: %s", table.concat(bolt_seq, ","))
    log("%s reason=%s | %s", ok and "PASS" or "FAIL", reason, state_line("end"))
    if logfh then logfh:flush() end
    manager.machine:exit()
end

local function cpu_pc()
    if not cpu then return nil end
    for _, name in ipairs({ "PC", "CURPC", "GENPC" }) do
        local ok, item = pcall(function() return cpu.state[name] end)
        if ok and item then
            local okv, v = pcall(function() return item.value end)
            if okv then return v end
        end
    end
    return nil
end

local function detect_corruption()
    local pc = cpu_pc()
    if pc and A.system_lockup ~= 0 and A.tvbp ~= 0
        and pc >= A.system_lockup and pc < A.tvbp then
        return "lockup_pc_" .. hx(pc)
    end
    local gs = r16(A.gstate)
    if gs == 0xffff or gs > 0x40 then return string.format("bad_gstate_0x%04x", gs) end
    local nobj, oerr = object_count()
    if oerr then return "objlist_" .. oerr end
    -- No tight object budget here: this fatality legitimately spawns a smoke
    -- puff every 4 ticks and then blows the victim into explode pieces and
    -- bones, so 60+ objects is the healthy case.  Only a runaway counts.
    if nobj > 220 then return "object_explosion_" .. nobj end
    local _, pcyc = count_procs()
    if pcyc then return "active_proc_cycle" end
    return nil
end

--------------------------------------------------------------------------
-- Setup / input
--------------------------------------------------------------------------
local function cache_fields()
    local wanted = {
        ["Coin 1"] = true, ["Coin 2"] = true, ["2 Players Start"] = true,
        ["P1 High Punch"] = true, ["P2 High Punch"] = true,
        ["P1 Left"] = true, ["P1 Right"] = true, ["P1 Low Kick"] = true,
        ["P1 High Kick"] = true, ["P1 Up"] = true,
    }
    for _, port in pairs(manager.machine.ioport.ports) do
        for _, field in pairs(port.fields) do
            if wanted[field.name] then fields[field.name] = field end
        end
    end
    local ok = true
    for name in pairs(wanted) do
        if not fields[name] then log("input %-16s MISSING", name); ok = false end
    end
    return ok
end

local function force_select()
    w16(A.p1_char, FT_RAIDEN)
    w16(A.p2_char, FT_VICTIM)
    w16(A.curback, STAGE_ID)
    if A.p1_state ~= 0 then w16(A.p1_state, PS_ACTIVE) end
    if A.p2_state ~= 0 then w16(A.p2_state, PS_ACTIVE) end
    if not did_direct_select then
        did_direct_select = true
        log("direct_select P1=Raiden(%d) P2=ochar(%d) stage=%d", FT_RAIDEN, FT_VICTIM, STAGE_ID)
    end
end

local function fighters_ok()
    local p1o, p2o = r32(A.p1_obj), r32(A.p2_obj)
    if p1o == 0 or p2o == 0 then return false end
    return r16(p1o + O.ochar) == FT_RAIDEN and r16(p2o + O.ochar) == FT_VICTIM
end

-- Reach FINISH HIM the way the game does: drain the victim and let the round
-- logic declare it.  Forcing winner_status=3 by hand with both bars full just
-- drops Raiden into his victory pose - the victim is never dizzy, so
-- fatality_xfer's "cmpi dizzy,a0" gate rejects every attempt.
local function force_finish_him()
    if fatal_frame ~= 0 then return end
    if not fighters_ok() then return end
    local rel = frame - fighting_frame
    if rel < 120 then return end
    -- FINISH HIM only comes up on the deciding round, so round 1 is a plain
    -- KO (drain and let it end) and round 2's KO is the one that offers it.
    if fight_count < 2 then
        if r16(A.p2_bar) > 0 then
            w16(A.p2_bar, 0)
            log("round1_ko frame=%d | %s", frame, state_line("ko1"))
        end
        return
    end
    if not victim_dizzy_forced then
        w16(A.p2_bar, 0)
        victim_dizzy_forced = true
        log("drained_p2 frame=%d | %s", frame, state_line("kill"))
    end
    local p1p = r32(A.p1_proc)
    if p1p ~= 0 and not REAL then
        w16(p1p + P.flags, r16(p1p + P.flags) & ~(PM_REACTING | PM_SITDUCK | PM_SPECIAL))
    end
    if finish_forced_frame == 0 and r16(A.winner_status) == 3 then
        finish_forced_frame = frame
        baseline_obj_count = select(1, object_count())
        log("finish_him frame=%d objs=%d | %s", frame, baseline_obj_count, state_line("ff"))
        snap("finish_him")
    end
end

-- fatality_xfer requires the victim's process to be parked in the dizzy
-- routine.  Same readiness test the Baraka finish-him harness uses.
local function victim_ready()
    local p = r32(A.p2_proc)
    if p == 0 then return false end
    local wake = r32(p + P.wake)
    return A.dizzy ~= 0 and wake >= A.dizzy and wake < (A.dizzy + 0x120)
end

local function snap_range(dist)
    local p1o, p2o = r32(A.p1_obj), r32(A.p2_obj)
    if p1o == 0 or p2o == 0 then return end
    local p2x = r16(p2o + O.oxpos)
    local x = p2x - (dist or SNAP_X)
    w16(p1o + O.oxpos, x)
    w32(p1o + O.oxval, (x << 16) & 0xffffffff)
end

-- "Forward" resolved live from which side P1 is standing on.
local function fwd_name()
    local p1o, p2o = r32(A.p1_obj), r32(A.p2_obj)
    if p1o == 0 or p2o == 0 then return "P1 Right" end
    if r16(p1o + O.oxpos) > r16(p2o + O.oxpos) then return "P1 Left" end
    return "P1 Right"
end

-- One attempt: press HK and HOLD it for HOLD_FRAMES (rd_hk_open wants 274
-- ticks, 5 seconds), then snap into range just before the release - the
-- release is what fires the fatality.  In FINISH HIM Raiden's HK press no
-- longer throws a kick (rd_hk_charge_only, MOVES.ASM), so RDLF_PRESS_DIST=60
-- (press next to the dizzy victim) must pass too.  RDLF_REAL=1 stops forcing
-- winner_status / clearing p1 flags and logs every gate (GATE lines).
-- RDLF_HOLD: how long HK is held before the release that fires the fatality.
-- The default over-holds on purpose, but an over-hold cannot DISCRIMINATE a
-- change to rd_lift_hold - 300 passes whether the gate is 164 or 274.  Set it
-- between the old and new values to prove which one is linked.
local HOLD_FRAMES = getenv_int("RDLF_HOLD", 300)
-- RDLF_TRACE=1: the per-30-frame GATE line (p1act included, so it shows
-- whether the high kick actually comes out) without RDLF_REAL's other changes.
local TRACE = (os.getenv("RDLF_TRACE") or "0") == "1"
local SNAP_FAR = tonumber(os.getenv("RDLF_PRESS_DIST") or "150")
local ATTEMPT_LEN = HOLD_FRAMES + 60
local function combo_press(name, rel)
    return name == "P1 High Kick" and rel >= 2 and rel < HOLD_FRAMES
end

local function pressed(name)
    if charsel_frame == 0 then
        if name == "Coin 1" or name == "Coin 2" then
            return frame >= 220 and frame < 6000 and (frame % 80) < 20
        end
        if name == "2 Players Start" then
            return frame >= 260 and frame < 6000 and (frame % 80) >= 30 and (frame % 80) < 55
        end
    end
    if charsel_frame > 0 and fighting_frame == 0 then
        if name == "P1 High Punch" and p1_confirm_start > 0 then
            return frame >= p1_confirm_start and frame < p1_confirm_start + 40
        end
        if name == "P2 High Punch" and p1_confirm_start > 0 then
            return frame >= p1_confirm_start + 80 and frame < p1_confirm_start + 120
        end
    end
    if combo_start_frame > 0 and fatal_frame == 0 and fighting_frame > 0 then
        return combo_press(name, (frame - combo_start_frame) % ATTEMPT_LEN)
    end
    return false
end

--------------------------------------------------------------------------
-- RDLF_OWNER (-Owner in the .ps1): Raiden's costume lane, written into
-- @alt_pal_owner every frame the way run_raiden_elec_test.ps1 claims it.
-- 0x0004 = Start+HP (RDALT1_P, RED current), 0x0010 = Start+LP (RDALT2_P,
-- PURPLE).  0 leaves the claim alone (his default, BLUE).
local OWNER = tonumber(os.getenv("RDLF_OWNER") or "0") or 0
local CAMTRACE = (os.getenv("RDLF_CAMTRACE") or "0") ~= "0"
local ct_y, ct_sky, ct_fd, ct_sh
-- RDLF_SYNCTRACE=1: while the fatality runs, every tick the VICTIM's pose
-- (oimg) or his palette (palram[map], the ROM address the allocator holds)
-- changes - so the shock flicker can be read against the pose steps.
local SYNCTRACE = (os.getenv("RDLF_SYNCTRACE") or "0") ~= "0"
local st_img, st_pal

local function on_frame()
    frame = frame + 1
    if OWNER ~= 0 and space and A.alt_pal_owner ~= 0 then
        w16(A.alt_pal_owner, OWNER)
    end
    -- RDLF_CAMTRACE=1: every change of the camera row (worldtly), the flash
    -- colour (irqskye - white_flash writes 0ffffh) and f_death, so the lift
    -- camera's rise, its cut under the pop's flash and its release can be read.
    if SYNCTRACE and space and s16(r16(A.f_death)) == 3 then
        local vo = r32(A.p2_obj)
        if vo ~= 0 then
            local img = select(1, obj_label(vo, all_sags)) or "?"
            img = img .. "/" .. tostring(select(1, find_bolt()) or "-")
            local map = (r16(vo + 0x140) >> 8) & 0xff
            local pal = r32(A.palram + map * 0x40)
            if img ~= st_img or pal ~= st_pal then
                log("SYNC frame=%d art=%s pal=%08x%s%s", frame, img, pal,
                    img ~= st_img and " POSE" or "", pal ~= st_pal and " PAL" or "")
                st_img, st_pal = img, pal
            end
        end
    end
    if CAMTRACE and space then
        local cy, sk, fd = s16(r16(A.worldtly + 16)), r16(A.irqskye), s16(r16(A.f_death))
        -- and the victim's m_shadow (oflags2 bit 4): is he casting one?
        local vo = r32(A.p2_obj)
        local sh = (vo ~= 0) and ((r16(vo + O.oflags2) & 0x10) ~= 0 and 1 or 0) or -1
        if cy ~= ct_y or sk ~= ct_sky or fd ~= ct_fd or sh ~= ct_sh then
            log("CAMTRACE frame=%d worldtly=%d irqskye=%04x f_death=%d vshadow=%d",
                frame, cy, sk, fd, sh)
            ct_y, ct_sky, ct_fd, ct_sh = cy, sk, fd, sh
        end
    end
    if frame == 1 then
        cpu = manager.machine.devices[":maincpu"]
        space = cpu.spaces["program"]
        if SND_TAP then
            local ok = pcall(function()
                snd_handle = space:install_write_tap(SND_LO, SND_HI, "rdlfsnd",
                    function(offset, data, mask)
                        if offset ~= SND_PORT then return data end
                        local w = data & 0xffff
                        if (w & 0xff00) ~= 0xff00 then snd_pending = nil; return data end
                        -- ROLLING pair, never a strict two-write pairing: one odd
                        -- write puts a strict one permanently out of phase.
                        local prev = snd_pending
                        snd_pending = w & 0xff
                        if prev == nil then return data end
                        snd_log[#snd_log + 1] = {code = (prev << 8) | snd_pending, f = frame}
                        return data
                    end)
            end)
            log("sound-latch tap: %s", (ok and snd_handle) and "installed" or "FAILED")
        end
        if not cache_fields() then finish(false, "input_missing"); return end
        log("Raiden F,F,F+LK lift fatality probe; observe=%d hang=%d do_raiden_lift_fatal=%s",
            OBSERVE, HANG_LIMIT, hx(A.do_raiden_lift_fatal))
    end
    if not space or finished then return end

    local gs = r16(A.gstate)
    if gs ~= last_gstate then
        if gs == GS_PSEL and charsel_frame == 0 then charsel_frame = frame end
        if gs == GS_FIGHTING and last_gstate ~= GS_FIGHTING then
            fight_count = fight_count + 1
            fighting_frame = frame
            log("fight_start frame=%d fight=%d | %s", frame, fight_count, state_line("fs"))
        end
        last_gstate = gs
    end

    if fighting_frame == 0 then
        force_select()
        if charsel_frame > 0 and p1_confirm_start == 0 and frame > charsel_frame + 90
            and r16(A.p1_char) == FT_RAIDEN and r16(A.p2_char) == FT_VICTIM then
            p1_confirm_start = frame + 25
        end
        for name, field in pairs(fields) do field:set_value(pressed(name) and 1 or 0) end
        return
    end

    if fatal_frame == 0 then
        force_finish_him()
        if combo_start_frame == 0 and finish_forced_frame > 0
                and (frame - finish_forced_frame) % 120 == 60 then
            -- still waiting on victim_ready(): say where he IS parked
            local vp = r32(A.p2_proc)
            log("WAITING victim wake=%08x dizzy=%08x (+%d)", vp ~= 0 and r32(vp + P.wake) or 0,
                A.dizzy, vp ~= 0 and (r32(vp + P.wake) - A.dizzy) or 0)
        end
        if combo_start_frame == 0 and finish_forced_frame > 0 and victim_ready() then
            combo_start_frame = frame
            snap_range()
            log("combo_start frame=%d | %s", frame, state_line("cs"))
        end
        if combo_start_frame > 0 then
            local rel = (frame - combo_start_frame) % ATTEMPT_LEN
            if rel == 0 then
                combo_attempt = combo_attempt + 1
                snap_range(SNAP_FAR)
                log("attempt %d frame=%d | %s", combo_attempt, frame, state_line("try"))
            end
            if rel == HOLD_FRAMES - 4 then snap_range() end   -- into range for the release
            -- Hold the finish-him window open: "that's all" would otherwise
            -- close it after ~10s and end the run before enough attempts land.
            if not REAL and r16(A.winner_status) ~= 3 then w16(A.winner_status, 3) end
            if (REAL or TRACE) and (rel % 30 == 0 or rel == HOLD_FRAMES or rel == HOLD_FRAMES + 1) then
                local p1p = r32(A.p1_proc)
                local p2p = r32(A.p2_proc)
                local tk = r16(A.tick)
                local st = r16(A.l_hk)
                log("GATE rel=%d tick=%d l_hk=%d tsl=%d ws=%d fdeath=%d lock=%d p1flags=%s p1act=%s p2wake=%s dizzy=%s",
                    rel, tk, st, (tk - st) & 0xffff, r16(A.winner_status), s16(r16(A.f_death)),
                    r16(A.f_fatal_lock), p1p ~= 0 and hx(r16(p1p + P.flags)) or "-",
                    p1p ~= 0 and hx(r16(p1p + P.action)) or "-",
                    p2p ~= 0 and hx(r32(p2p + P.wake)) or "-", hx(A.dizzy))
            end
        end
        if s16(r16(A.f_death)) == FATAL_NUM then
            fatal_frame = frame
            if CLIMB > 0 and climb_saved == nil then
                climb_saved = r16(A.climb_limit)
                w16(A.climb_limit, CLIMB)
                log("CLIMB preview: climb_limit %d -> %d for the fatality", climb_saved, CLIMB)
            end
            local p2o = r32(A.p2_obj)
            vic_y_start = p2o ~= 0 and s16(r16(p2o + O.oypos)) or 0
            log("FATALITY STARTED frame=%d after %d attempts | %s",
                frame, combo_attempt, state_line("go"))
            snap("fatality_start")
        end
        if combo_attempt > 6 then finish(false, "fatality_never_triggered"); return end
        for name, field in pairs(fields) do field:set_value(pressed(name) and 1 or 0) end
        return
    end

    -- ---- fatality is live: watch it ----
    local rel = frame - fatal_frame
    if CAMUP > 0 and fatal_frame > 0 and cam_state ~= 3 then
        local y = s16(r16(A.worldtly + 16))
        if cam_state == 0 then
            cam_home = y
            w16(A.f_noscrolly, 1)
            cam_state = 1
            log("CAMUP preview: chase frozen, easing %d px up from y=%d", CAMUP, y)
        end
        local want = (cam_state == 1 and fatal_end_frame == 0) and (cam_home - CAMUP) or cam_home
        if cam_state == 1 and fatal_end_frame > 0 then cam_state = 2 end
        if y > want then y = math.max(want, y - CAMSPD)
        elseif y < want then y = math.min(want, y + CAMSPD) end
        w16(A.worldtly + 16, y)
        if cam_state == 2 and y == cam_home then
            w16(A.f_noscrolly, 0)
            cam_state = 3
            log("CAMUP preview: back at y=%d, chase released", y)
        end
    end
    if climb_saved ~= nil and fatal_end_frame > 0 then
        w16(A.climb_limit, climb_saved)      -- the stage's own cap back
        log("CLIMB preview: climb_limit restored to %d", climb_saved)
        climb_saved = nil
    end
    -- The mash: Up held, HP tapped, for as long as the fatality runs.
    for name, field in pairs(fields) do
        local on = false
        if MASH and fatal_end_frame == 0 and rel >= MASH_FROM then
            if name == "P1 Up" then on = MASH_UP_HOLD or (frame % 6) < 3 end
            if name == "P1 High Punch" then on = (frame % 6) < 3 end
        end
        field:set_value(on and 1 or 0)
    end
    if fatal_end_frame > 0 and vic_y_after == nil and frame >= fatal_end_frame + 60 then
        local p2o = r32(A.p2_obj)
        vic_y_after = p2o ~= 0 and s16(r16(p2o + O.oypos)) or -999
        log("victim y=%d one second after the fatality ended (y=%d when it started)",
            vic_y_after, vic_y_start)
        snap("after_end")
    end

    -- The victim's head falls out of the sky: r_raiden_superp (MKDIE.ASM) waits
    -- 0xa0 ticks after the explosion, then drops his a_head frame from above the
    -- screen and bounces it.  Nothing guarantees his process is still his by
    -- then, so watch for it rather than assume.
    do
        local p1o, p2o, hobj, hlab = r32(A.p1_obj), r32(A.p2_obj), nil, nil
        -- After the pop (the WAX timeline is over), debris is every explode_piece
        -- (MKDIE.ASM): oid_bones (010ch), still moving until bone_land's stop_a8.
        -- Nothing else counts - Raiden's victory lightning and the win text move
        -- for the rest of the round.
        local popped = wax_t0 ~= nil and frame - wax_t0 >= WAX_TOTAL
        local moving = 0
        walk(function(obj)
            if obj == p1o or obj == p2o then return end
            if not hobj then
                local lab = select(1, obj_label(obj, all_sags))
                if lab and lab:find("HEAD", 1, true) then hobj, hlab = obj, lab; return end
            end
            if popped and r16(obj + O.oid) == 0x010c
                and (r32(obj + O.oxvel) ~= 0 or r32(obj + O.oyvel) ~= 0) then
                moving = moving + 1
            end
        end)
        if moving > 0 then debris_last_rel, debris_frames = rel, debris_frames + 1 end
        if hobj then
            local hx, hy = s16(r16(hobj + O.oxpos)), s16(r16(hobj + O.oypos))
            if head_first == 0 then
                head_first, head_rel = frame, rel
                log("HEAD appears rel=%d %s at (%d,%d)", rel, hlab, hx, hy)
            end
            head_frames = head_frames + 1
            -- A head carrying the body's multipart/inviso bits is on the list,
            -- moving, and never drawn: exactly the retail superp head.
            local f2 = r16(hobj + O.oflags2)
            if (f2 & 0x0022) ~= 0 then
                head_undrawable = head_undrawable + 1
                if head_undrawable == 1 then
                    log("HEAD NOT DRAWABLE rel=%d %s oflags2=0x%04x (multipart/inviso)", rel, hlab, f2)
                end
            end
            if head_lowest == nil or hy > head_lowest then head_lowest = hy end
            if head_min_y == nil or hy < head_min_y then head_min_y, head_peak_rel = hy, rel end
            if hy ~= head_last_y then head_settle_rel, head_last_y = rel, hy end
            if head_prev_y then
                local d = hy - head_prev_y
                if d < 0 and head_dir > 0 and rel > head_peak_rel then
                    head_bounces = head_bounces + 1
                end
                if d ~= 0 then head_dir = d end
            end
            head_prev_y = hy
            local top = s16(r16(A.worldtly + 0x10))
            if hy + r16(hobj + O.osizey) < top then head_went_up = true end
            if (frame - head_first) % 8 == 0 then
                log("HEAD rel=%d %s at (%d,%d)", rel, hlab, hx, hy)
                snap(string.format("head_%03d", rel))
            end
        end
    end

    local bad = detect_corruption()
    if bad then finish(false, bad .. "_at_rel_" .. rel); return end

    local p1o = r32(A.p1_obj)
    local rlab, rsag = obj_label(p1o, raiden_sags)
    if rlab ~= last_body then
        if #body_seq > 0 then body_seq[#body_seq] = body_seq[#body_seq] .. "x" .. body_hold end
        body_seq[#body_seq + 1] = rlab or ("?" .. hx(rsag))
        last_body = rlab
        body_hold = 0
    end
    body_hold = body_hold + 1
    local blab, bsag = find_bolt()
    if blab ~= last_bolt then
        if blab then bolt_seq[#bolt_seq + 1] = blab end
        last_bolt = blab
    end

    -- WAX alignment, frame by frame from the frame the bolt first appears: the
    -- step the WAX timeline says is showing must be the one on screen.
    if fatal_end_frame == 0 and wax_t0 == nil and blab then wax_t0 = frame end
    if MASH and fatal_end_frame == 0 and wax_t0 then
        local t = frame - wax_t0
        local p2o = r32(A.p2_obj)
        if t < WAX_TOTAL and p1o ~= 0 and p2o ~= 0 then
            local row, start = 1, 0
            while t >= start + WAX_SEQ[row].frames do
                start = start + WAX_SEQ[row].frames
                row = row + 1
            end
            local want = WAX_SEQ[row]
            -- A fighter's osag is stale; the drawn piece is the first SAG in his
            -- multipart RAM (oimg), so name the pose from that.
            local vimg = r32(p2o + O.oimg)
            local vraw = vimg ~= 0 and r32(vimg) or 0
            local vlab = all_sags[vraw] or all_sags[vraw & 0x00ffffff] or ("?" .. hx(vraw))
            local rflip = (r16(p1o + O.oflags) & M_FLIPH) ~= 0
            local vflip = (r16(p2o + O.oflags) & M_FLIPH) ~= 0
            local vdown = (r16(p2o + O.oflags) & M_FLIPV) ~= 0
            local dx = s16(r16(p2o + O.oxpos)) - s16(r16(p1o + O.oxpos))
            local dy = s16(r16(p2o + O.oypos)) - s16(r16(p1o + O.oypos))
            local ex = rflip and -want.x or want.x
            local eflip = (rflip ~= want.m)
            local edown = want.v == true
            -- KLUDGE_X is a hand-carried copy of X (palette added) on the same
            -- SAG, so the SAG lookup may name either one: compare them as equal.
            local function unkludge(l) return (tostring(l):gsub('^KLUDGE_', '')) end
            local pose_ok = vlab:find(want.pose, 1, true) ~= nil
            for _, l in ipairs(SAG_ALIASES[vraw] or SAG_ALIASES[vraw & 0x00ffffff] or {}) do
                if l:find(want.pose, 1, true) then pose_ok = true end
            end
            local ok = rlab == want.body and unkludge(blab) == unkludge(want.bolt)
                and pose_ok
                and dx == ex and dy == want.y and vflip == eflip and vdown == edown
            wax_checked = wax_checked + 1
            if t == start then
                wax_rows = wax_rows + 1
                log("WAX step %2d t=%-3d body=%s bolt=%s vic=%s d=(%d,%d) want=(%d,%d) flip=%s/%s vflip=%s/%s %s",
                    row, t, tostring(rlab), tostring(blab), vlab, dx, dy, ex, want.y,
                    tostring(vflip), tostring(eflip), tostring(vdown), tostring(edown),
                    ok and "ok" or "MISMATCH")
            end
            -- Snapshot MID-step: on a step's first frame the screen still shows
            -- what was drawn before the processes changed it.
            if t == start + want.frames // 2 then
                snap(string.format("step%02d_%s", row, tostring(rlab)))
            end
            if not ok then
                wax_bad = wax_bad + 1
                if wax_bad <= 5 then
                    log("WAX MISMATCH t=%d step %d: body=%s want %s | bolt=%s want %s | vic=%s want %s | d=(%d,%d) want (%d,%d) | flip=%s want %s | vflip=%s want %s",
                        t, row, tostring(rlab), want.body, tostring(blab), want.bolt,
                        vlab, want.pose, dx, dy, ex, want.y, tostring(vflip), tostring(eflip),
                        tostring(vdown), tostring(edown))
                end
            end
        elseif t == WAX_TOTAL and blab then
            wax_bad = wax_bad + 1
            log("WAX TIMING bolt %s still up %d frames after it appeared (WAX runs %d)",
                blab, t, WAX_TOTAL)
        end
    end

    -- The core detector: Raiden drawing art that is in no Raiden table means
    -- the frame walker ran off the end of its animation list into raw ROM.
    if fatal_end_frame == 0 and rlab == nil and p1o ~= 0 then
        unknown_hits = unknown_hits + 1
        if unknown_hits == 1 then
            log("UNKNOWN body SAG %s at rel=%d | %s", hx(rsag), rel, state_line("bad"))
            snap("unknown_body_sag")
        end
        if unknown_hits > 3 then
            finish(false, string.format("body_off_table_sag_%s_rel_%d", hx(rsag), rel))
            return
        end
    end

    if rel <= 40 or rel % 15 == 0 then log("rel=%-4d | %s", rel, state_line("obs")) end
    if rel == 1 or rel == 30 or rel == 60 or rel == 90 or rel == 130 or rel == 200 then
        snap(string.format("fat_%03d", rel))
    end

    if fatal_end_frame == 0 and s16(r16(A.f_death)) ~= FATAL_NUM then
        fatal_end_frame = frame
        log("death_blow_complete frame=%d rel=%d | %s", frame, rel, state_line("done"))
        snap("fatality_complete")
    end

    if fatal_end_frame == 0 and rel > HANG_LIMIT then
        finish(false, "fatality_hung_rel_" .. rel)
        return
    end

    if fatal_end_frame > 0 and frame - fatal_end_frame >= OBSERVE then
        if #body_seq > 0 and not body_seq[#body_seq]:find("x%d+$") then
            body_seq[#body_seq] = body_seq[#body_seq] .. "x" .. body_hold
        end
        log("WAX: %d rows, %d frames checked, %d mismatched", wax_rows, wax_checked, wax_bad)
        log("HEAD: first seen rel=%d, on screen %d frames, lowest y=%s",
            head_rel, head_frames, tostring(head_lowest))
        log("HEAD LAST: peak y=%s at rel=%d (above the frame: %s), settled rel=%d; debris last moved rel=%d (%d frames moving)",
            tostring(head_min_y), head_peak_rel, tostring(head_went_up), head_settle_rel,
            debris_last_rel, debris_frames)
        log("HEAD BOUNCES: %d (need %d)", head_bounces, HEAD_MIN_BOUNCES)
        if unknown_hits > 0 then
            finish(false, "off_table_frames_" .. unknown_hits)
        elseif not MASH then
            local fd = s16(r16(A.f_death))
            log("FIZZLE: head seen=%s, debris frames=%d, victim y after=%s (start %d), f_death=%d",
                tostring(head_first ~= 0), debris_frames, tostring(vic_y_after), vic_y_start, fd)
            if head_first ~= 0 or debris_frames > 0 then
                finish(false, "fizzle_but_it_exploded")
            elseif vic_y_after == nil or vic_y_after < vic_y_start - 40 then
                finish(false, "fizzle_body_not_on_the_floor_y_" .. tostring(vic_y_after))
            elseif fd ~= 0 then
                finish(false, "fizzle_f_death_" .. fd)
            else
                finish(true, "fizzle_body_dropped_y_" .. vic_y_after)
            end
        elseif wax_checked ~= WAX_TOTAL then
            finish(false, string.format("wax_checked_%d_of_%d_frames", wax_checked, WAX_TOTAL))
        elseif head_first == 0 then
            finish(false, "head_never_fell")
        elseif head_undrawable > 0 then
            finish(false, "head_not_drawable_" .. head_undrawable)
        elseif debris_frames == 0 then
            finish(false, "debris_motion_not_measured")
        elseif not head_went_up then
            finish(false, "head_never_flew_up")
        elseif head_first ~= 0 and head_settle_rel >= (frame - fatal_frame) - 2 then
            -- still moving when observation stopped: the window was too short to see
            -- it land, so neither the bounce count nor "last" can be judged
            finish(false, string.format("head_still_moving_at_rel_%d_raise_Observe", head_settle_rel))
        elseif head_bounces < HEAD_MIN_BOUNCES then
            finish(false, "head_bounced_only_" .. head_bounces)
        elseif head_settle_rel <= debris_last_rel then
            finish(false, string.format("head_settled_rel_%d_before_debris_rel_%d",
                head_settle_rel, debris_last_rel))
        elseif wax_bad > 0 then
            finish(false, "wax_mismatch_frames_" .. wax_bad)
        else
            finish(true, string.format("completed_in_%d_frames_body=%d_bolt=%d",
                fatal_end_frame - fatal_frame, #body_seq, #bolt_seq))
        end
        return
    end

    if frame > 12000 then finish(false, "global_timeout"); return end
end

-- MAME swallows Lua errors raised inside a frame callback: the script simply
-- stops running and the emulation keeps going to the backstop with no verdict.
-- Wrap it so a bug in the harness reports itself instead of looking like a
-- silent no-repro.
emu.register_frame(function()
    if finished then return end
    local ok, err = pcall(on_frame)
    if not ok then
        log("LUA ERROR frame=%d: %s", frame, tostring(err))
        finish(false, "harness_lua_error")
    end
end)
